use crate::db::Db;

const IMPORT_TECH_MAP: &[(&str, &str)] = &[
    ("rusqlite", "sqlite"),
    ("sqlx", "sql"),
    ("tokio", "async"),
    ("serde", "serialization"),
    ("serde_json", "json"),
    ("flutter", "flutter"),
    ("http", "http"),
    ("hyper", "http"),
    ("reqwest", "http"),
    ("tonic", "grpc"),
    ("prost", "grpc"),
    ("tracing", "observability"),
