### Step 3: Implement `enrich` function

```rust
fn enrich(db: &Db, explicit_anchors: &[(AnchorKind, &str)]) -> Enrichment {
    let mut seen_dirs: HashSet<String> = HashSet::new();
    let mut seen_imports: HashSet<String> = HashSet::new();
    let mut cats: HashSet<String> = HashSet::new();
    let mut anchors = Vec::new();

    for &(kind, value) in explicit_anchors {
        let file_row = match kind {
            AnchorKind::Symbol => {
                db.resolve_symbol(value, None)
                    .ok()
                    .flatten()
                    .and_then(|sym| db.file_by_id(sym.file_id).ok().flatten())
            }
            AnchorKind::File => db.file_by_path(value).ok().flatten(),
            _ => continue,
        };

        let Some(file) = file_row else { continue };

        // Directory anchor from parent path
        if let Some(dir) = file.path.rsplit_once('/').map(|(d, _)| d) {
            if seen_dirs.insert(dir.to_string()) {
                anchors.push((AnchorKind::Directory, dir.to_string()));
            }
        }

        // Language category
        let lang = file.language.to_lowercase();
        if !lang.is_empty() {
            cats.insert(lang);
        }

        // Import-derived anchors and technology categories
        let imports = db.imports_for_file(file.id).unwrap_or_default();
        for imp in &imports {
            let root = import_root(&imp.imported_path);
            if !root.is_empty() && seen_imports.insert(root.to_string()) {
                anchors.push((AnchorKind::ImportPattern, format!("{root}::*")));
                if let Some(&(_, tech)) = IMPORT_TECH_MAP.iter().find(|&&(k, _)| k == root) {
                    cats.insert(tech.to_string());
                }
            }
        }
    }

    Enrichment { anchors, categories: cats.into_iter().collect() }
}

fn import_root(imported_path: &str) -> &str {
    // Dart: "package:flutter/material.dart" → "flutter"
    if let Some(rest) = imported_path.strip_prefix("package:") {
        return rest.split('/').next().unwrap_or("");
    }
    // Dart: "dart:core" → skip (stdlib, not useful as tech category)
    if imported_path.starts_with("dart:") {
        return "";
    }
    // Rust: "rusqlite::params" → "rusqlite"
    imported_path.split("::").next().unwrap_or("")
}
```

### Step 4: Integrate enrichment into `handle`

Change `handle` signature:
```rust
pub fn handle(lessons_db: &LessonsDb, workspace_db: Option<&Db>, args: &RememberArgs) -> Result<serde_json::Value>
```

After building `anchors` and `cats` from explicit inputs, merge enrichment:
```rust
let enrichment = workspace_db.map(|db| enrich(db, &anchors));

let mut all_anchors: Vec<(AnchorKind, &str)> = anchors;
let mut all_cats: Vec<&str> = cats;
let owned_anchor_strings: Vec<(AnchorKind, String)>;
let owned_cat_strings: Vec<String>;

if let Some(e) = enrichment {
    owned_anchor_strings = e.anchors;
    owned_cat_strings = e.categories;
    // Add enriched anchors that aren't already explicit
    for (k, v) in &owned_anchor_strings {
        if !all_anchors.iter().any(|(ek, ev)| ek == k && *ev == v.as_str()) {
            all_anchors.push((*k, v.as_str()));
        }
    }
    for c in &owned_cat_strings {
        if !all_cats.iter().any(|&ec| ec == c.as_str()) {
            all_cats.push(c.as_str());
        }
    }
}
```

Update response to report enrichment:
```rust
Ok(json!({
    "stored": true,
    "lesson_id": id,
    "anchor_count": all_anchors.len(),
    "enriched": workspace_db.is_some(),
}))
```

### Step 5: Update MCP handler

In `src/mcp.rs`, change `sutra_remember`:
```rust
pub async fn sutra_remember(
    &self,
    Parameters(args): Parameters<RememberArgs>,
) -> Result<String, ErrorData> {
    let ws_db = args.workspace.as_deref()
        .and_then(|ws| self.get_db(ws).ok());
    let result = tools::remember::handle(
        &self.lessons_db,
        ws_db.as_deref(),
        &args,
    ).map_err(sutra_to_rmcp)?;
    to_compact_json(result)
}
```

### Step 6: Write tests

Create `tests/remember-enrichment-test.rs` with test cases using a workspace DB seeded with files and imports:

1. **symbol anchor enrichment**: Store a lesson with a symbol anchor → verify import-pattern, directory, language category are auto-added
2. **file anchor enrichment**: Store with a file anchor → same verifications
3. **explicit + inferred merge**: Explicit categories preserved, inferred ones added alongside
4. **no workspace DB**: Pass None → stores with explicit anchors only, no error
5. **symbol not found**: Symbol doesn't exist in workspace → stores with explicit anchors, no error
6. **dedup**: File appears in multiple anchors → directory/import anchors not duplicated

Tests will need a helper that creates a workspace `Db`, inserts files and imports, then calls `handle` and inspects the LessonsDb to verify stored anchors/categories.

